CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,picture TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires BIGINT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth(state TEXT PRIMARY KEY,verifier TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id),slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL,data TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credentials(email TEXT PRIMARY KEY,user_id TEXT UNIQUE NOT NULL REFERENCES users(id),salt TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,starts BIGINT NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rsvps(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,name TEXT NOT NULL,attendance TEXT NOT NULL CHECK(attendance IN ('attending','not_attending','unsure')),guests INTEGER NOT NULL CHECK(guests BETWEEN 0 AND 10),message TEXT NOT NULL,updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS rsvps_event_updated ON rsvps(event_id, updated);
CREATE TABLE IF NOT EXISTS rsvp_limits(key TEXT PRIMARY KEY,starts BIGINT NOT NULL,count INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_owner_updated ON events(owner,updated);
CREATE INDEX IF NOT EXISTS photos_event ON photos(event_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
